var WSTRIP={"weeks":[["2026-W35","24 Aug 2026",3,[],["F34","F35","F36","F37"],0],["2026-W36","31 Aug 2026",1,[],[],0],["2026-W37","7 Sep 2026",2,[],[],0],["2026-W38","14 Sep 2026",0,[],[],0],["2026-W39","21 Sep 2026",19,[["2026-09-24","595ffd9a","pages","Header and footer edges sat a few pixels off the body text on six pages, copied from a shared template.","Aligned all six; a lint now fails any page whose header or footer padding differs from its body.","gutter_consistency_lint"],["2026-09-26","06c93e77","compass","Saved decisions never recorded their time horizon or review date, so follow-up reminders ran on a blind default.","Both save paths store them now, and reminder timing scales with the horizon.","receipt_timing_gate"],["2026-09-26","ce2b504b","nftt","About nine older field-note posts lacked the required title and description tags; the check only ran on files being edited.","Fixed all nine and added a check that reads every post at once.","nftt_meta_gate"]],["F38","F39","F40","F41"],0],["2026-W40","28 Sep 2026",12,[],["F42"],1],["2026-W41","5 Oct 2026",16,[["2026-10-05","90743bf5","forge","Generated résumés carried the wrong location line, copied forward from old templates.","Pinned the line at the source and corrected 183 lines; a gate checks every résumé.","resume_location_gate"],["2026-10-05","190e662b","cruft-sweep","The worktree cleanup tool could back up the wrong branch for a detached or broken worktree.","It now proves each target is a real worktree with its own history, and refuses otherwise.","cruft_sweep"],["2026-10-06","c1be4cc7","handoff","The handoff archiver kept notes by position, so it could archive a newer note and keep an older one.","It sorts by version now, and the hook warns when a handoff note is written by hand.","handoff_fold"],["2026-10-08","8ef6dab3","universe","A committed snapshot counted commits, so it went stale with every commit by design.","The check covers content only; the counts refresh on their own schedule.","universe_snapshot_emit"],["2026-10-08","bac67125","design-system","A design-system card printed raw JavaScript template code instead of its values.","Rebuilt the card as static markup; a lint blocks template code left in any page.","template_leak_lint"],["2026-10-08","a01afc10","design","Two retired grey text colours, too faint to read, were still hardcoded across served pages.","Swapped them out and recorded design debt per page; the count may only go down.","design_debt_sweep"]],[],0],["2026-W42","12 Oct 2026",12,[["2026-10-17","bbed234a","artifacts","The zoom buttons in a DJ tool did nothing, because two elements shared one id.","Fixed the ids and added a static review of the tool's sources.","phosphor_static_review"]],[],0],["2026-W43","19 Oct 2026",1,[],[],0],["2026-W44","26 Oct 2026",9,[["2026-10-30","2e616122","ui","A review found status chips could drift from the shared colours and fall under the contrast floor.","The chip generator's check now fails on either, on every commit.","grammar_chips_emit"]],[],0],["2026-W45","2 Nov 2026",8,[["2026-11-08","1d101fee","client","On a client's project page, clicking a workstream collapsed it and the day columns left a blank strip.","Fixed both, and added a test that clicks through the page.","client_hub_crawl"]],["F43","F44","F45","F46","F47","F48"],0],["2026-W46","9 Nov 2026",9,[["2026-11-12","12822415","share","Share buttons on sign-in-only pages copied the page's own link, so the person it was sent to hit a 404.","The buttons create a share link now; the same bug had come back three times before.","share_control_gate"],["2026-11-12","b3b8dda8","recoil","A public share link showed more of an internal page than intended: lines were removed from a list, not allowed in.","Public views are an allow-list now, and a gate checks the signed-out page.","recoil_public_share_gate, recoil_public_share_render"],["2026-11-12","a715c92e","scripts","Self-tests run from a commit hook wrote into the real repository's settings, so commits went out under a test identity.","All 17 self-tests drop git's environment first, and a gate checks for it.","scratch_git_leak_gate"]],[],0]],"max":19,"beliefs":"https://status.arcs.care/beliefs","source":"Source: git history of the pre-commit hook, 24 Aug 2026 to 13 Nov 2026: 92 gates wired, 16 of them by a fix commit (1 not shown here), each cited by commit and described in plain words, with client names removed. Reversals from the belief log."};
/* Kit organism 72, week strip and chains. arcsWeekStrip(host, data, {pick}) replaces host's content.
   data: {weeks: [[week, monday, gates, chains[[date, sha, scope, break, repair, gate]], reversals[id], withheld]], max, beliefs, source}.
   Shading strength 0.75x (Zach's pick, 2026-11-13). Vanilla DOM, no dependencies. */
function arcsWeekStrip(host, data, opts) {
  var SHADE = 0.75, W = data.weeks, pick = opts && opts.pick !== undefined ? opts.pick : W.length - 1;
  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text !== undefined) n.textContent = text;
    return n;
  }
  function cols() { return getComputedStyle(grid).gridTemplateColumns.split(' ').length; }
  function plural(n, one, many) { return n + " " + (n === 1 ? one : many); }
  function counts(w) {
    var s = plural(w[2], "gate", "gates") + " wired, " + plural(w[3].length + w[5], "chain", "chains");
    return w[5] ? s + " (" + w[5] + " not shown)" : s;
  }
  host.textContent = "";
  var grid = el("div", "ws-grid"), read = el("div", "ws-read"), head = el("div", "ws-rhead"), body = el("div"), cells = [];
  head.setAttribute("aria-live", "polite");
  read.appendChild(head);
  read.appendChild(body);
  grid.setAttribute("role", "group");
  grid.setAttribute("aria-label", "Weeks, oldest first");
  W.forEach(function (w, i) {
    var b = el("button", "ws-cell"), dots = el("span", "ws-dots");
    b.type = "button";
    b.tabIndex = -1;
    b.setAttribute("aria-label", "Week of " + w[1] + ": " + counts(w) + ", " + plural(w[4].length, "belief", "beliefs") + " reversed");
    b.style.background = "color-mix(in srgb, var(--cyan) " + Math.round(SHADE * (6 + 44 * w[2] / data.max)) + "%, var(--surface))";
    b.appendChild(el("span", "ws-n", String(w[2])));
    b.appendChild(el("span", "ws-mon", w[1].replace(/ \d{4}$/, "")));
    dots.setAttribute("aria-hidden", "true");
    [w[2], w[3].length + w[5], w[4].length].forEach(function (n, k) { if (n) dots.appendChild(el("span", "ws-dot ws-d" + k)); });
    b.appendChild(dots);
    b.addEventListener("click", function () { show(i); });
    b.addEventListener("keydown", function (e) {
      var j = { ArrowRight: i + 1, ArrowLeft: i - 1, ArrowDown: i + cols(), ArrowUp: i - cols(), Home: 0, End: W.length - 1 }[e.key];
      if (j === undefined) return;
      e.preventDefault();
      j = Math.max(0, Math.min(W.length - 1, j));
      show(j);
      cells[j].focus();
    });
    cells.push(b);
    grid.appendChild(b);
  });
  var key = el("ul", "ws-key");
  ["gates wired", "chains: a fix that added a gate", "beliefs reversed"].forEach(function (t, k) {
    var li = el("li");
    li.appendChild(el("span", "ws-dot ws-d" + k));
    li.appendChild(document.createTextNode(t));
    key.appendChild(li);
  });
  function step(k, v) {
    var s = el("div", "ws-step");
    s.appendChild(el("span", "ws-k", k));
    s.appendChild(v);
    return s;
  }
  function show(i) {
    var w = W[i];
    cells.forEach(function (c, j) { c.setAttribute("aria-pressed", String(j === i)); c.tabIndex = j === i ? 0 : -1; });
    head.textContent = "Week of " + w[1] + " · " + counts(w);
    body.textContent = "";
    if (w[4].length) {
      head.appendChild(document.createTextNode(" · "));
      var a = el("a", "", plural(w[4].length, "belief", "beliefs") + " reversed");
      a.title = w[4].join(", ");
      a.href = data.beliefs;
      head.appendChild(a);
    }
    if (!w[3].length) { body.appendChild(el("p", "ws-empty", w[5] ? "This week's chain is not shown on the public page." : "No fix commit added a gate this week.")); return; }
    var list = el("ul");
    list.style.listStyle = "none";
    w[3].forEach(function (c) {
      var li = el("li", "ws-chain"), brk = el("span", "ws-v");
      brk.appendChild(el("span", "ws-chip", c[2]));
      brk.appendChild(document.createTextNode(c[3]));
      li.appendChild(step("1 Break", brk));
      var fix = el("span", "ws-v", c[4] + " ");
      fix.appendChild(el("span", "ws-meta", c[1] + " · " + c[0]));
      li.appendChild(step("2 Repair", fix));
      li.appendChild(step("3 Gate", el("span", "ws-v ws-gate", c[5])));
      list.appendChild(li);
    });
    body.appendChild(list);
  }
  host.appendChild(grid);
  host.appendChild(key);
  host.appendChild(read);
  host.appendChild(el("p", "ws-src", data.source));
  show(pick);
}

